let homeAttentionExpanded=false;
function renderHomeAttention(){
 const stats=$('#homeAttentionStats'),list=$('#homeAttentionList');
 if(!stats||!list)return;
 try{
  const report=window.AIWalletModules.attention.overview(state.accounts,localDateKey());
  stats.innerHTML=`<div><strong>${report.urgentTrials}</strong><small>Trials needing attention</small></div><div><strong>${report.missingTrials}</strong><small>Trial details to review</small></div><div><strong>${report.missingRenewals}</strong><small>Renewal dates missing</small></div><div><strong>${money(report.projected30)}</strong><small>Next 30 days · estimated</small></div>`;
  list.innerHTML=report.rows.length?report.rows.slice(0,homeAttentionExpanded?report.rows.length:6).map(row=>`<div class="history-item attention-item"><div><span class="attention-type attention-type-${esc(row.kind)}">${row.kind==='trial'?'Trial deadline':row.kind==='trial_end'?'Trial ending':row.kind==='payment'?'Payment':'Needs review'}</span><b>${esc(row.label)}</b><small>${esc(row.message)}${row.date?' · '+esc(row.date):''}${row.kind==='payment'?' · '+money(row.amount):''}</small></div><button class="secondary" type="button" data-home-attention="${esc(row.accountId)}">Review</button></div>`).join('')+(report.hidden?`<button type="button" class="secondary attention-expand" data-attention-expand aria-expanded="${homeAttentionExpanded}">${homeAttentionExpanded?'Show fewer':`Show all ${report.rows.length} alerts`}</button>`:''):'<div class="empty">No upcoming alerts within your configured warning periods or missing renewal dates.</div>';
  $$('[data-home-attention]').forEach(button=>button.onclick=()=>editAccount(button.dataset.homeAttention));
  $$('[data-attention-expand]').forEach(button=>button.onclick=()=>{homeAttentionExpanded=!homeAttentionExpanded;renderHomeAttention()});
 }catch(error){stats.textContent='Deadline overview unavailable';list.textContent='Check your saved subscription and trial dates.'}
}
