['fileSearch','fileProvider','fileType','fileSort'].forEach(id=>$('#'+id).addEventListener(id==='fileSearch'?'input':'change',()=>{if(id==='fileType')activeFolder=$('#fileType').value;renderFiles()}));
async function downloadFile(id){let f=state.files.find(x=>x.id===id);if(!f)return;try{let blob=await getFileBlob(id);if(!blob&&f.data)blob=dataUrlToBlob(f.data);if(!blob)throw Error('File data not found');let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=window.AIWalletModules.fileSafety.safeFilename(f.name);a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}catch(e){toast('Could not retrieve this file from browser storage')}}async function previewFile(id){
 let f=state.files.find(x=>x.id===id);if(!f)return;
 if(!window.AIWalletModules.fileSafety.canInlinePreview(f)){toast('This file type is download-only for safety');await downloadFile(id);return}
 let w=window.open('about:blank','_blank');if(w)w.opener=null;
 try{
  let blob=await getFileBlob(id);if(!blob&&f.data)blob=dataUrlToBlob(f.data);if(!blob)throw Error('Missing file');
  if(!window.AIWalletModules.fileSafety.canInlinePreview({name:f.name,type:blob.type})){if(w)w.close();toast('File type requires download');await downloadFile(id);return}
  let url=URL.createObjectURL(blob);
  if(w)w.location.href=url;else{let a=document.createElement('a');a.href=url;a.download=window.AIWalletModules.fileSafety.safeFilename(f.name);a.click()}
  setTimeout(()=>URL.revokeObjectURL(url),60000);
 }catch(e){if(w)w.close();toast('Preview unavailable for this file')}
}
let backupExportBusy=false;async function exportBackup(){if(backupExportBusy||fileUploadBusy||window._walletImportBusy){toast('Wait for the current file operation to finish');return}backupExportBusy=true;try{let backup=window.AIWalletModules.backup.createEnvelope(state),missing=[];for(let f of state.files){let blob=await getFileBlob(f.id);if(!blob&&f.data)blob=dataUrlToBlob(f.data);if(!blob)missing.push(f.name);backup.files.push({...f,data:blob?await blobToDataUrl(blob):null})}if(missing.length&&!confirm(`${missing.length} file(s) have missing contents. This backup will contain their records but not their files. Export anyway?`))return;let blob=new Blob([JSON.stringify(backup)],{type:'application/json'});window.AIWalletModules.backup.assertBackupSize(blob.size);let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='domain-backup.json';a.style.display='none';document.body.appendChild(a);try{a.click()}finally{a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}toast(missing.length?`Backup exported with ${missing.length} missing file(s)`:'Wallet backup exported')}catch(e){console.error('Backup export failed',e);toast('Backup export failed: check file storage and the 100 MB backup limit.')}finally{backupExportBusy=false}}
$('#backupBtn').onclick=exportBackup;$('#exportBtn').onclick=exportBackup;$('#importBtn').onclick=()=>openModal('importModal');$('#backupInput').onchange=e=>{let f=e.target.files[0];if(!f)return;if(window._walletImportBusy||fileUploadBusy||backupExportBusy){toast('Wait for the current file operation to finish');e.target.value='';return}window._walletImportBusy=true;if(f.size>window.AIWalletModules.backup.MAX_BACKUP_BYTES){toast('Backup exceeds the 100 MB import limit');e.target.value='';window._walletImportBusy=false;return}let r=new FileReader();r.onload=async()=>{let previous=cloneState(state),written=[],previousRaw=null,previousUsage=null,metadataCommitted=false;try{previousRaw=localStorage.getItem(DATA_KEY);let parsed=JSON.parse(r.result);window.AIWalletModules.backup.validateBackup(parsed);const incompleteFiles=parsed.files.filter(file=>file.data==null);if(incompleteFiles.length&&!confirm(`${incompleteFiles.length} file(s) in this backup have no recoverable contents. Importing will preserve their metadata but cannot restore the missing files. Continue?`)){toast('Backup import cancelled');return}let rawIds=new Set(),fileIdMap=new Map(),staged=[];for(let file of parsed.files){if(!file||typeof file.id!=='string'||!file.id||rawIds.has(file.id))throw Error('Invalid or duplicate file entry');rawIds.add(file.id);if(file.data!=null&&typeof file.data!=='string')throw Error('Invalid file payload');let newId=id();fileIdMap.set(file.id,newId);if(typeof file.data==='string'){if(!window.AIWalletModules.backup.isBase64DataUrl(file.data))throw Error('Invalid file data');let blob=dataUrlToBlob(file.data);window.AIWalletModules.backup.assertBlobSize(blob);staged.push([newId,blob])}}let x=normalizeState(parsed);x.files=x.files.map(file=>{const {data,...metadata}=file;return {...metadata,id:fileIdMap.get(file.id)||id()}});for(let [fid,blob] of staged){await putFileBlob(fid,blob);written.push(fid)}previousUsage=await readUsageEvents();await replaceUsageEvents(x.usageHistory||[]);state=x;if(!save())throw Error('Could not save backup metadata');metadataCommitted=true;selectedService=state.services[0]?.id||'chatgpt';selectedAccount=state.accounts[0]?.id||'';render();$('#importModal').classList.remove('open');$('#backupInput').value='';toast('Backup imported')}catch(err){state=previous;try{const currentRaw=localStorage.getItem(DATA_KEY);if(metadataCommitted||previousRaw!==currentRaw){if(previousRaw===null)localStorage.removeItem(DATA_KEY);else localStorage.setItem(DATA_KEY,previousRaw)}}catch(rollbackError){console.error('Backup metadata rollback failed',rollbackError)}if(previousUsage!==null)try{await replaceUsageEvents(previousUsage)}catch(rollbackError){console.error('Usage rollback failed',rollbackError)}for(let fid of written)try{await deleteFileBlob(fid)}catch(cleanupError){}console.error('Backup import failed',err);toast('Backup import failed: file is invalid, too large, or browser storage is full')}finally{window._walletImportBusy=false;$('#backupInput').value=''}};r.onerror=()=>{window._walletImportBusy=false;toast('Backup could not be read');e.target.value=''};r.onabort=()=>{window._walletImportBusy=false;e.target.value=''};try{r.readAsText(f)}catch(error){window._walletImportBusy=false;e.target.value='';toast('Backup could not be opened')}};$('#clearBtn').onclick=async()=>{if(window._walletImportBusy||fileUploadBusy||backupExportBusy){toast('Wait for file operations to finish before resetting');return}if(confirm('Delete all locally saved DomAIn data? Export a backup first if you need it.')){let previous=cloneState(state);state=emptyState();selectedAccount='';selectedService='chatgpt';if(!save()){state=previous;render();return}try{await window.AIWalletModules.storage.clearWalletStores()}catch(e){state=previous;save();render();toast('Could not clear all browser storage. Your wallet data was restored where possible.');return}render();toast('Local wallet reset')}};

function renderCreator(){
 const root=$('#creatorDashboard');if(!root)return;
 const domain=window.AIWalletModules.creator, c=state.creator, report=domain.report(c,localDateKey());
 const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v);
 $('#creatorExpected').textContent=money(report.expected);
 $('#creatorReceived').textContent=money(report.received);
 $('#creatorOutstanding').textContent=money(report.outstanding);
 if(document.activeElement!==$('#creatorGoal'))$('#creatorGoal').value=c.goal||'';
 $('#creatorGoalProgress').textContent=c.goal>0?`${Math.round(report.received/c.goal*100)}% of ${money(c.goal)} monthly goal`:'Set a monthly income goal';
 const intel=window.AIWalletModules.intelligence;
 const today=localDateKey();
 const queue=intel.actionQueue(c,state.accounts,today);
 $('#creatorActions').innerHTML=queue.length?queue.map(x=>`<div class="history-item"><div><b>${esc(x.subject)}</b><small>${esc(x.detail)} · ${esc(x.date)}${x.days<0?' · '+Math.abs(x.days)+' days overdue':''}</small></div><strong>${x.amount?money(x.amount):'!'}</strong></div>`).join(''):'<div class="empty">No immediate creator or subscription actions.</div>';
 const cash=intel.cashForecast(c,today);
 $('#creatorCashForecast').innerHTML=cash.months.map(x=>`<div class="history-item"><div><b>${esc(x.month)}</b><small>Scheduled contracts ${money(x.scheduled)} · Recorded pending ${money(x.pending)}</small></div><strong>${money(x.received)} <small>received</small></strong></div>`).join('');
 const scenarios=window.AIWalletModules.revenuePlanning.scenarios(c,today);
 $('#creatorScenarios').innerHTML=scenarios.months.map(x=>`<div class="history-item"><div><b>${esc(x.month)}</b><small>Conservative ${money(x.scenarios.conservative)} · Base ${money(x.scenarios.base)} · Optimistic ${money(x.scenarios.optimistic)}</small></div><strong>${money(x.contracted)} <small>scheduled</small></strong></div>`).join('');
 const health=window.AIWalletModules.analytics.analyze(c,today);
 $('#creatorRevenueHealth').innerHTML=`<div class="history-item"><div><b>Overdue creator payouts</b><small>1–30 days ${money(health.aging.days1to30)} · 31–60 days ${money(health.aging.days31to60)} · 61+ days ${money(health.aging.days61plus)}</small></div><strong>${money(health.totals.overdue)}</strong></div><div class="history-item"><div><b>Monthly contracted recurring revenue</b><small>${health.recurring.length} client(s) · excludes one-time agreements</small></div><strong>${money(health.monthlyRecurring)}</strong></div><div class="history-item"><div><b>Largest-client concentration</b><small>${esc(health.recurring[0]?.client||'No active recurring clients')} · share of contracted recurring revenue</small></div><strong>${health.largestClientSharePercent}%</strong></div><div class="history-item"><div><b>Income goal remaining</b><small>Received payouts dated this month · ${health.goal.progressPercent===null?'no goal set':health.goal.progressPercent+'% of goal'}</small></div><strong>${money(health.goal.remaining)}</strong></div>`;
 const collections=window.AIWalletModules.collections.worklist(c,today);
 $('#creatorCollections').innerHTML=`<div class="history-item"><div><b>${collections.rows.length} pending payouts · ${money(collections.summary.overdue)} overdue</b><small>${money(collections.summary.critical)} over 30 days late · ${money(collections.summary.dueSoon)} due within 7 days · ${collections.summary.missingReferences} without references</small></div></div>`+(collections.rows.length?collections.rows.slice(0,30).map(x=>`<div class="history-item"><div><b>${esc(x.client||'Unassigned client')}</b><small>${esc(x.dueDate||'Date missing')} · ${esc(x.priority)}${x.days>0?' · '+x.days+' days late':''}${x.reference?' · '+esc(x.reference):' · reference missing'}</small></div><strong>${money(x.amount)}</strong></div>`).join(''):'<div class="empty">No pending payouts to follow up.</div>');
 const checks=intel.reconciliation(c);
 $('#creatorReconciliation').innerHTML=`<div class="history-item"><div><b>${checks.duplicateReferences.length} duplicate payout reference(s)</b><small>Potential duplicate records to review manually</small></div></div><div class="history-item"><div><b>${checks.unreferencedReceived} received payout(s) without references</b><small>Add a transaction reference for easier verification</small></div></div>`;
 const dataHealth=window.AIWalletModules.dataHealth.inspect(state);
 $('#creatorDataHealth').innerHTML=`<div class="history-item"><div><b>${dataHealth.counts.error} errors · ${dataHealth.counts.warning} warnings · ${dataHealth.counts.info} notices</b><small>Read-only integrity review · records are not automatically changed</small></div></div>`+dataHealth.issues.slice(0,20).map(x=>`<div class="history-item"><div><b>${esc(x.kind.replaceAll('-',' '))}</b><small>${esc(x.detail)} · ${esc(x.recordId)}</small></div></div>`).join('');
 const review=window.AIWalletModules.reconciliationReview.review(c);
 $('#creatorReviewQueue').innerHTML=`<div class="history-item"><div><b>${review.summary.issueCount} review issue(s) · ${review.matches.length} suggested match(es)</b><small>${money(review.summary.pendingAmount)} pending · ${money(review.summary.receivedAmount)} received</small></div></div>`+(review.issues.map(x=>`<div class="history-item"><div><b>${esc(x.kind.replaceAll('-',' '))}</b><small>${esc(x.detail)} · payout ${esc(x.payoutIds.join(', '))}</small></div></div>`).join(''))+(review.matches.map(x=>`<div class="history-item"><div><b>Possible agreement match</b><small>Payout ${esc(x.payoutId)} · agreement ${esc(x.agreementId)} · not verified</small></div></div>`).join(''));
 $('#creatorForecast').innerHTML=report.forecast.map(x=>`<div class="history-item"><div><b>${esc(x.month)}</b><small>Contracted recurring income · estimate</small></div><strong>${money(x.amount)}</strong></div>`).join('');
 $('#creatorAgreements').innerHTML=c.agreements.length?c.agreements.map(a=>`<div class="history-item"><div><b>${esc(a.client)}</b><small>${esc(a.title)} · ${esc(a.cadence)} · ${esc(a.status)}${a.nextDue?' · due '+esc(a.nextDue):''}</small></div><div><strong>${money(a.amount)}</strong> <button class="secondary" data-remove-agreement="${esc(a.id)}" aria-label="Delete agreement">×</button></div></div>`).join(''):'<div class="empty">No creator agreements recorded yet.</div>';
 $('#creatorPayouts').innerHTML=c.payouts.length?c.payouts.slice().sort((a,b)=>b.dueDate.localeCompare(a.dueDate)).map(x=>`<div class="history-item"><div><b>${esc(x.client)}</b><small>${esc(x.dueDate)} · ${esc(x.status)}${x.reference?' · '+esc(x.reference):''}</small></div><div><strong>${money(x.amount)}</strong> <button class="secondary" data-toggle-payout="${esc(x.id)}">${x.status==='received'?'Mark pending':'Mark received'}</button> <button class="secondary" data-remove-payout="${esc(x.id)}" aria-label="Delete payout">×</button></div></div>`).join(''):'<div class="empty">No payouts recorded yet.</div>';
 $$('[data-remove-agreement]').forEach(b=>b.onclick=()=>creatorMutate(c=>{c.agreements=c.agreements.filter(a=>a.id!==b.dataset.removeAgreement)}));
 $$('[data-remove-payout]').forEach(b=>b.onclick=()=>creatorMutate(c=>{c.payouts=c.payouts.filter(a=>a.id!==b.dataset.removePayout)}));
 $$('[data-toggle-payout]').forEach(b=>b.onclick=()=>creatorMutate(c=>{let x=c.payouts.find(a=>a.id===b.dataset.togglePayout);if(x)x.status=x.status==='received'?'pending':'received'}));
}
$('#exportCollections').onclick=()=>downloadCreatorCsv('ai-wallet-collections.csv',window.AIWalletModules.collections.exportCsv(window.AIWalletModules.collections.worklist(state.creator,localDateKey())));
function downloadCreatorCsv(name,content){const blob=new Blob([content],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let pendingCreatorImport=null,creatorCsvText='',creatorCsvToken=0;
const csvFields=[['client','Client *'],['amount','Amount *'],['dueDate','Payment date *'],['status','Status *'],['reference','Transaction reference'],['currency','Currency']];
function clearCreatorPreview(message=''){
 pendingCreatorImport=null;$('#creatorImportConfirm').hidden=true;$('#creatorImportPreview').textContent=message;
}
function showCreatorMapping(headers){
 const aliases={client:['client','payer','brand'],amount:['amount','grossamount'],dueDate:['duedate','date','paymentdate'],status:['status','paymentstatus'],reference:['reference','transactionreference','transactionid','invoice'],currency:['currency','currencycode']};
 const normalized=headers.map(window.AIWalletModules.payoutImport.normalizeHeader);
 const holder=$('#creatorCsvMappingFields');holder.replaceChildren();
 for(const [field,title] of csvFields){
  const label=document.createElement('label');label.textContent=title;label.className='tiny';
  const select=document.createElement('select');select.dataset.csvField=field;select.setAttribute('aria-label',title);
  const blank=document.createElement('option');blank.value='';blank.textContent='Not mapped';select.appendChild(blank);
  headers.forEach((name,index)=>{const opt=document.createElement('option');opt.value=String(index);opt.textContent=`${index+1}: ${name||'(unnamed)'}`;select.appendChild(opt)});
  const found=normalized.findIndex(n=>aliases[field].includes(n));if(found>=0)select.value=String(found);
  select.addEventListener('change',()=>clearCreatorPreview('Mapping changed. Preview again before importing.'));
  label.appendChild(select);holder.appendChild(label);
 }
 $('#creatorCsvMapping').hidden=false;
}
function creatorCsvOptions(){
 const mapping={};for(const select of $$('#creatorCsvMappingFields select'))if(select.value!=='')mapping[select.dataset.csvField]=Number(select.value);
 return {mapping,rejectUnreferencedDuplicates:$('#creatorImportFuzzy').checked};
}
function previewCreatorCsv(){
 clearCreatorPreview();if(!creatorCsvText)return;
 try{
  const opts=creatorCsvOptions();
  const result=window.AIWalletModules.payoutImport.preview(creatorCsvText,state.creator.payouts,opts);
  pendingCreatorImport={csv:creatorCsvText,options:opts,rows:result.accepted};
  $('#creatorImportPreview').textContent=`${result.accepted.length} valid payout(s), ${result.duplicates.length} duplicate(s), ${result.rejected.length} invalid row(s), ${result.unreferenced} without transaction references. `+result.rejected.slice(0,8).map(x=>`Row ${x.row}: ${x.reason}`).join(' · ');
  $('#creatorImportConfirm').hidden=!result.accepted.length;
 }catch(err){clearCreatorPreview('Import rejected: '+err.message)}
}
$('#creatorPayoutCsv').addEventListener('change',async e=>{
 const token=++creatorCsvToken;creatorCsvText='';$('#creatorCsvMapping').hidden=true;clearCreatorPreview();
 const file=e.target.files?.[0];if(!file)return;
 if(file.size>1024*1024){clearCreatorPreview('CSV exceeds the 1 MB limit.');return}
 try{
  const content=await file.text();if(token!==creatorCsvToken)return;
  const parsed=window.AIWalletModules.payoutImport.parseCSV(content);creatorCsvText=content;
  showCreatorMapping(parsed[0]);previewCreatorCsv();
 }catch(err){clearCreatorPreview('Import rejected: '+err.message)}
});
$('#creatorCsvPreviewBtn').onclick=previewCreatorCsv;
$('#creatorImportFuzzy').addEventListener('change',()=>clearCreatorPreview('Duplicate policy changed. Preview again before importing.'));
$('#creatorImportConfirm').onclick=()=>{
 if(!pendingCreatorImport?.rows.length)return;
 // Always re-run the exact preview against current records before committing.
 let result;try{result=window.AIWalletModules.payoutImport.preview(pendingCreatorImport.csv,state.creator.payouts,pendingCreatorImport.options)}
 catch(err){clearCreatorPreview('Revalidation failed: '+err.message);return}
 const fresh=result.accepted;if(!fresh.length){clearCreatorPreview('No new payouts remain after revalidation.');return}
 const previous=cloneState(state);state.creator.payouts.push(...fresh.map(p=>({...p,id:id()})));
 if(!commitState(previous))return;
 creatorCsvText='';pendingCreatorImport=null;$('#creatorCsvMapping').hidden=true;$('#creatorImportConfirm').hidden=true;$('#creatorPayoutCsv').value='';
 $('#creatorImportPreview').textContent=`Imported ${fresh.length} user-recorded payout(s). No transactions were bank-verified.`;
 renderCreator();toast(`${fresh.length} payouts imported`);
};
$('#exportCreatorLedger').onclick=()=>{downloadCreatorCsv('ai-wallet-creator-ledger.csv',window.AIWalletModules.revenuePlanning.exportLedger(state.creator));toast('Creator ledger CSV exported')};
$('#exportCreatorReview').onclick=()=>{downloadCreatorCsv('ai-wallet-reconciliation-review.csv',window.AIWalletModules.reconciliationReview.exportReview(state.creator));toast('Reconciliation review CSV exported')};
$('#exportCreatorForecast').onclick=()=>{downloadCreatorCsv('ai-wallet-creator-forecast.csv',window.AIWalletModules.revenuePlanning.exportForecast(state.creator,localDateKey()));toast('Forecast CSV exported')};
function creatorMutate(fn){const previous=cloneState(state);fn(state.creator);if(commitState(previous))renderCreator()}
$('#creatorGoalForm').onsubmit=e=>{e.preventDefault();let goal=Number($('#creatorGoal').value);if(!Number.isFinite(goal)||goal<0)return toast('Enter a valid income goal');creatorMutate(c=>{c.goal=goal});toast('Income goal saved')};
$('#creatorAgreementForm').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;let amount=Number(f.elements.amount.value);if(!Number.isFinite(amount)||amount<=0)return toast('Enter a valid agreement amount');creatorMutate(c=>c.agreements.push({id:id(),client:f.elements.client.value.trim().slice(0,120),title:f.elements.title.value.trim().slice(0,120),amount,cadence:f.elements.cadence.value,status:f.elements.status.value,nextDue:f.elements.nextDue.value}));f.reset();toast('Agreement saved')};
$('#creatorPayoutForm').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;let amount=Number(f.elements.amount.value);if(!Number.isFinite(amount)||amount<=0)return toast('Enter a valid payout amount');creatorMutate(c=>c.payouts.push({id:id(),client:f.elements.client.value.trim().slice(0,120),amount,dueDate:f.elements.dueDate.value,status:f.elements.status.value,reference:f.elements.reference.value.trim().slice(0,120)}));f.reset();toast('Payout saved')};

if('serviceWorker' in navigator&&location.protocol!=='file:'){window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(error=>console.warn('Offline support unavailable',error)))}
initStorage().then(async()=>{applyDueResets();applyDueChatRefreshes();render();await auditFileStorage()}).catch(()=>{render();auditFileStorage()});

// Reminder preferences are separate from wallet backups and are stored on this device.
const reminderModule=window.AIWalletModules.reminders;
let reminderPrefs=reminderModule.load();
function renderReminders(){
 const enabled=$('#remindersEnabled'),lead=$('#reminderLead'),list=$('#reminderList');if(!list)return;
 enabled.checked=reminderPrefs.enabled;lead.value=String(reminderPrefs.leadDays);
 const today=localDateKey(),items=reminderModule.entries(state.accounts,today,reminderPrefs);
 $('#reminderCount').textContent=items.length+' active';
 list.innerHTML=items.length?items.map(item=>`<div class="history-item"><div><b>${esc(item.title)}</b><small>${esc(item.body)} · ${esc(item.date)} · ${item.days<0?Math.abs(item.days)+' days overdue':item.days===0?'Today':item.days+' days remaining'}</small></div><button class="secondary" data-snooze-reminder="${esc(item.key)}" type="button">Snooze 1 day</button></div>`).join(''):'<div class="empty">No active reminders within your warning window.</div>';
 $$('[data-snooze-reminder]').forEach(button=>button.onclick=()=>{reminderPrefs=reminderModule.save(reminderModule.snooze(reminderPrefs,button.dataset.snoozeReminder,reminderModule.nextDay(today)));renderReminders()});
 $('#notificationStatus').textContent=!('Notification' in window)?'This browser does not support the Notification API.':`Browser permission: ${Notification.permission}. Notifications are triggered only while the app is open.`;
}
$('#remindersEnabled').onchange=e=>{reminderPrefs=reminderModule.save({...reminderPrefs,enabled:e.target.checked});renderReminders()};
$('#reminderLead').onchange=e=>{reminderPrefs=reminderModule.save({...reminderPrefs,leadDays:Number(e.target.value)});renderReminders()};
$('#requestNotification').onclick=async()=>{
 if(!('Notification' in window)||!window.isSecureContext)return toast('Browser notifications require a supported browser and HTTPS or localhost');
 try{const permission=await Notification.requestPermission();renderReminders();toast(permission==='granted'?'Browser notifications enabled while the app is open':'Browser notification permission not granted')}catch{toast('Notification permission request failed')}
};
async function notifyOpenAppReminders(){
 if(!('Notification' in window)||Notification.permission!=='granted'||!('serviceWorker' in navigator)||!reminderPrefs.enabled)return;
 const today=localDateKey();const items=reminderModule.entries(state.accounts,today,reminderPrefs).filter(item=>item.days>=0&&item.days<=1&&reminderPrefs.delivered[item.key]!==today);
 if(!items.length)return;
 try{const registration=await navigator.serviceWorker.ready;for(const item of items.slice(0,5)){await registration.showNotification(item.title,{body:item.body,tag:'aiwallet-'+item.key,icon:'./assets/ai-wallet-icon.svg'});reminderPrefs=reminderModule.save(reminderModule.markDelivered(reminderPrefs,item.key,today))}}catch(error){console.warn('Browser notification unavailable:',error)}
}
window.addEventListener('focus',()=>{renderReminders();notifyOpenAppReminders()});
window.addEventListener('load',()=>{renderReminders();notifyOpenAppReminders()});

// Export the user's manually entered deadlines to a standard calendar file.
$('#exportDeadlineCalendar').onclick=()=>{
 try{const module=window.AIWalletModules.calendarExport;const horizonDays=Number($('#calendarHorizon').value);const options={today:localDateKey(),horizonDays};const events=module.calendarEvents(state.accounts,options);if(!events.length)return toast('No valid trial or renewal deadlines to export');
 const payload=module.generate(state.accounts,new Date().toISOString(),options);const url=URL.createObjectURL(new Blob([payload],{type:'text/calendar;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='ai-wallet-subscription-deadlines.ics';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Calendar exported. Import it into your calendar app to activate its reminders.')}catch(error){console.error(error);toast('Calendar export failed')}
};

function renderTrialTimeline(){
 const summary=document.querySelector('#trialTimelineSummary'),list=document.querySelector('#trialTimelineList');
 if(!summary||!list)return;
 try{
  const report=window.AIWalletModules.trialTimeline.trialTimeline(state.accounts,localDateKey());
  summary.innerHTML=`<div class="stats" style="margin:12px 0"><div class="stat"><small>ACTIVE TRIALS</small><strong>${report.active}</strong></div><div class="stat"><small>DEADLINE ATTENTION</small><strong>${report.urgent}</strong></div><div class="stat"><small>DETAILS TO REVIEW</small><strong>${report.missing}</strong></div></div>`;
  list.innerHTML=report.entries.length?report.entries.map(e=>{
   const deadline=e.daysToCancel===null?'Cancellation date not entered':e.daysToCancel<0?`${Math.abs(e.daysToCancel)} day(s) past cancellation deadline — verify provider status`:e.daysToCancel===0?'Cancellation deadline today':`${e.daysToCancel} day(s) until cancellation deadline`;
   const details=`${e.trialDays?e.trialDays+'-day offer · ':''}Trial ends ${e.trialEnd||'unknown'} · ${deadline}`;
   return `<div class="history-item"><div><b>${esc(e.label)}</b><small>${esc(details)}</small>${e.issues.length?`<small style="color:var(--warning,#e6a950)">${esc(e.issues.join(' · '))}</small>`:''}</div><button type="button" class="secondary" data-trial-edit="${esc(e.accountId)}">Edit</button></div>`;
  }).join(''):'<div class="empty">No active free trials. Add an account with a trial to monitor its cancellation date.</div>';
  document.querySelectorAll('[data-trial-edit]').forEach(button=>button.onclick=()=>editAccount(button.dataset.trialEdit));
 }catch(error){summary.textContent='Trial overview unavailable';list.textContent='Review your saved trial dates.'}
}
// Forecast uses the same recurrence calculation as renewal reminders.
function renderPaymentForecast(){
 const summary=document.querySelector('#paymentForecastSummary'),list=document.querySelector('#paymentForecastList'),select=document.querySelector('#paymentForecastWindow');
 if(!summary||!list||!select)return;
 try{
  const result=window.AIWalletModules.paymentForecast.summary(state.accounts,localDateKey(),Number(select.value));
  const nextPaymentMarkup=result.nextPayment?`<div class="forecast-next" role="status"><span>Next estimated payment day</span><strong>${esc(result.nextPayment.date)} · ${money(result.nextPayment.amount)}</strong><small>${result.nextPayment.days===0?'Today':result.nextPayment.days===1?'Tomorrow':`In ${result.nextPayment.days} days`} · ${result.nextPayment.count} payment${result.nextPayment.count===1?'':'s'}</small></div>`:'';
  const missingRenewalMarkup=result.missingDateAccounts.length?`<div class="forecast-missing"><b>Renewal dates needed</b><small>These paid profiles are excluded from the estimate until a date is added.</small>${result.missingDateAccounts.slice(0,8).map(a=>`<div class="forecast-missing-row"><span>${esc(a.label)}</span><button class="secondary" type="button" data-forecast-review="${esc(a.accountId)}">Add date</button></div>`).join('')}${result.missingDateAccounts.length>8?`<small>Showing 8 of ${result.missingDateAccounts.length} profiles needing dates.</small>`:''}</div>`:'';
  summary.innerHTML=`<div class="stats" style="margin:12px 0"><div class="stat"><small>PROJECTED PAYMENTS</small><strong>${result.count}</strong></div><div class="stat"><small>ESTIMATED TOTAL (USD)</small><strong>${money(result.total)}</strong></div><div class="stat"><small>NEXT 7 DAYS</small><strong>${money(result.dueSoonTotal)}</strong></div><div class="stat"><small>ACCOUNTS</small><strong>${result.accounts}</strong></div><div class="stat"><small>RENEWAL DATES TO ADD</small><strong>${result.missingDates}</strong></div></div>`;
  list.innerHTML=nextPaymentMarkup+missingRenewalMarkup+(result.events.length?`<div class="forecast-dates"><strong>Payment days</strong><div class="forecast-date-chips">${result.byDate.slice(0,8).map(d=>`<span class="forecast-date-chip">${esc(d.date)} <b>${money(d.total)}</b> <small>${d.count} payment${d.count===1?'':'s'}</small></span>`).join('')}</div></div>`+result.events.slice(0,40).map(e=>`<div class="history-item"><div><b>${esc(e.label)}</b><small>${esc(e.date)} · ${esc(e.cycle)} · scheduled estimate</small></div><div class="file-actions"><strong>${money(e.amount)}</strong><button class="secondary" type="button" data-forecast-review="${esc(e.accountId)}" aria-label="Review subscription for ${esc(e.label)}">Review</button></div></div>`).join('')+(result.events.length>40?`<p class="tiny muted">Showing 40 of ${result.events.length} projected payments; totals include all.</p>`:''):'<div class="empty">No scheduled paid renewals with valid dates in this window. Check accounts missing renewal dates above.</div>');
 $$('[data-forecast-review]').forEach(button=>button.onclick=()=>editAccount(button.dataset.forecastReview));
 }catch(error){summary.textContent='Forecast unavailable';list.textContent='Check your saved subscription dates.'}
}
document.querySelector('#paymentForecastWindow')?.addEventListener('change',renderPaymentForecast);
